+// API keys, roles and the audit log. Keys live in the data as
+// `apiKeys: [{ key, name, role }]`. Roles are ordered: a viewer may read, a
+// cook may also do kitchen work, a manager may do everything. Every request
+// that changes data leaves an audit entry (docs/DATA.md).
+import { timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+/** Whether `role` has at least the `needed` access ("viewer", "cook" or "manager"). */
+export function allows(role, needed) {
+  const have = ROLES.indexOf(role);
+  return have >= 0 && have >= ROLES.indexOf(needed);
+}
+
+function sameKey(a, b) {
+  const x = Buffer.from(String(a));
+  const y = Buffer.from(String(b));
+  return x.length === y.length && timingSafeEqual(x, y);
+}
+
+/** The key record for a key string, or null when it is unknown. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) if (sameKey(k.key, key) && ROLES.includes(k.role)) found = k;
+  return found;
+}
+
+/** Appends an audit entry { id, at, keyName, method, path, status } and returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
